"""Demo A: an exact 1-toughness checker and resilience report.

Given a small graph, this computes its component count over every deletion set,
certifies (or refutes) 1-toughness directly from the definition, and reports the
worst-case scattering ratio |S| / comp(G, S) that witnesses toughness.
"""

from __future__ import annotations

from itertools import combinations
from typing import Dict, FrozenSet, List, Set, Tuple

Vertex = int
Graph = Tuple[Set[Vertex], Set[FrozenSet[Vertex]]]


def make_graph(n: int, edges: List[Tuple[int, int]]) -> Graph:
    return (set(range(n)), {frozenset(e) for e in edges})


def num_comp(G: Graph, S: Set[Vertex]) -> int:
    V, E = G
    keep = V - S
    adj: Dict[Vertex, Set[Vertex]] = {v: set() for v in keep}
    for e in E:
        a, b = tuple(e)
        if a in keep and b in keep:
            adj[a].add(b)
            adj[b].add(a)
    seen: Set[Vertex] = set()
    comps = 0
    for start in keep:
        if start in seen:
            continue
        comps += 1
        stack = [start]
        while stack:
            u = stack.pop()
            if u in seen:
                continue
            seen.add(u)
            stack.extend(adj[u] - seen)
    return comps


def toughness_report(G: Graph) -> Dict[str, object]:
    V = list(G[0])
    connected = num_comp(G, set()) == 1
    worst_ratio = float("inf")
    worst_witness: Tuple[Tuple[int, ...], int] = ((), 0)
    tough = connected
    for r in range(1, len(V) + 1):
        for S in combinations(V, r):
            c = num_comp(G, set(S))
            if c >= 2:
                ratio = len(S) / c
                if ratio < worst_ratio:
                    worst_ratio = ratio
                    worst_witness = (S, c)
                if c > len(S):
                    tough = False
    return {
        "connected": connected,
        "is_one_tough": tough,
        "min_scattering_ratio": worst_ratio,
        "tightest_witness": worst_witness,
    }


def main() -> None:
    graphs = {
        "C5 (5-cycle)": make_graph(5, [(i, (i + 1) % 5) for i in range(5)]),
        "K4": make_graph(4, list(combinations(range(4), 2))),
        "Path P4": make_graph(4, [(0, 1), (1, 2), (2, 3)]),
    }
    for name, G in graphs.items():
        rep = toughness_report(G)
        print(f"{name}: {rep}")


if __name__ == "__main__":
    main()

"""Demo C: the complete-graph forbidden-pattern dichotomy.

For a library of small patterns, this tests the equivalence
    K_n contains H (induced)  <=>  H is complete (has no non-edge),
by brute-force induced-subgraph search inside complete graphs of increasing size.
It confirms the dichotomy holds for every pattern whenever n >= |V(H)|.
"""

from __future__ import annotations

from itertools import combinations, permutations
from typing import Dict, FrozenSet, List, Set, Tuple

Vertex = int
Graph = Tuple[Set[Vertex], Set[FrozenSet[Vertex]]]


def graph(n: int, edges: List[Tuple[int, int]]) -> Graph:
    return (set(range(n)), {frozenset(e) for e in edges})


def complete(n: int) -> Graph:
    return (set(range(n)), {frozenset(e) for e in combinations(range(n), 2)})


def adj(G: Graph, a: Vertex, b: Vertex) -> bool:
    return frozenset((a, b)) in G[1]


def has_non_edge(H: Graph) -> bool:
    return any(not adj(H, a, b) for a, b in combinations(H[0], 2))


def contains_induced(H: Graph, G: Graph) -> bool:
    HV, GV = list(H[0]), list(G[0])
    if len(HV) > len(GV):
        return False
    for image in permutations(GV, len(HV)):
        f: Dict[Vertex, Vertex] = dict(zip(HV, image))
        if all(adj(H, a, b) == adj(G, f[a], f[b]) for a, b in combinations(HV, 2)):
            return True
    return False


def main() -> None:
    patterns = {
        "K1+P4": graph(5, [(1, 2), (2, 3), (3, 4)]),
        "P3": graph(3, [(0, 1), (1, 2)]),
        "K3": complete(3),
        "K4": complete(4),
        "paw": graph(4, [(0, 1), (1, 2), (2, 0), (2, 3)]),
    }
    for name, H in patterns.items():
        k = len(H[0])
        Kn = complete(k)
        predicted = not has_non_edge(H)  # H complete => contained
        observed = contains_induced(H, Kn)
        print(f"{name:6}: has_non_edge={has_non_edge(H)!s:5}  "
              f"K{k} contains it={observed!s:5}  predicted={predicted!s:5}  "
              f"[match={observed == predicted}]")


if __name__ == "__main__":
    main()

