"""Algorithm 1: component count after deletion via union-find."""

from __future__ import annotations

from typing import Dict, FrozenSet, List, Set, Tuple


class DisjointSet:
    def __init__(self, elements: Set[int]) -> None:
        self.parent: Dict[int, int] = {e: e for e in elements}
        self.rank: Dict[int, int] = {e: 0 for e in elements}

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1


def num_comp(vertices: Set[int], edges: Set[FrozenSet[int]],
             deleted: Set[int]) -> int:
    """Number of connected components of G - `deleted`.

    Runs in near-linear O((V + E) alpha(V)) time via union-find.
    """
    keep = vertices - deleted
    dsu = DisjointSet(keep)
    for e in edges:
        a, b = tuple(e)
        if a in keep and b in keep:
            dsu.union(a, b)
    return len({dsu.find(v) for v in keep})


def main() -> None:
    V = set(range(6))
    E = {frozenset((i, (i + 1) % 6)) for i in range(6)} | {frozenset((0, 3))}
    for S in [set(), {0}, {0, 3}, {1, 4}]:
        print(f"comp(G, {sorted(S)}) = {num_comp(V, E, S)}")


if __name__ == "__main__":
    main()

