"""Algorithm 2: exact 1-toughness verification by scattering-set search."""

from __future__ import annotations

from itertools import combinations
from typing import Dict, FrozenSet, List, Optional, Set, Tuple


def num_comp(V: Set[int], E: Set[FrozenSet[int]], S: Set[int]) -> int:
    keep = V - S
    adj: Dict[int, Set[int]] = {v: set() for v in keep}
    for e in E:
        a, b = tuple(e)
        if a in keep and b in keep:
            adj[a].add(b)
            adj[b].add(a)
    seen: Set[int] = set()
    comps = 0
    for start in keep:
        if start in seen:
            continue
        comps += 1
        stack = [start]
        while stack:
            u = stack.pop()
            if u in seen:
                continue
            seen.add(u)
            stack.extend(adj[u] - seen)
    return comps


def verify_one_tough(V: Set[int],
                     E: Set[FrozenSet[int]]) -> Tuple[bool, Optional[Set[int]]]:
    """Return (is_one_tough, witness). If not tough, witness is a set S with
    comp(G,S) > |S| and comp(G,S) >= 2. Exhaustive: O(2^|V| * (V+E))."""
    if num_comp(V, E, set()) != 1:
        return (False, set())
    verts = list(V)
    for r in range(1, len(verts)):
        for S in combinations(verts, r):
            c = num_comp(V, E, set(S))
            if c >= 2 and c > r:
                return (False, set(S))
    return (True, None)


def main() -> None:
    # Petersen-like small example: the 5-cycle is 1-tough.
    V = set(range(5))
    E = {frozenset((i, (i + 1) % 5)) for i in range(5)}
    print("C5:", verify_one_tough(V, E))
    # Star is not 1-tough: deleting the center scatters it.
    Vs = set(range(5))
    Es = {frozenset((0, i)) for i in range(1, 5)}
    print("Star:", verify_one_tough(Vs, Es))


if __name__ == "__main__":
    main()

