function CONTAINS_IN_COMPLETE(n_host, H_vertices, H_edges):
    if |H_vertices| > n_host: return (False, none)   // size obstruction
    for each pair {a, b} of distinct H_vertices:
        if {a, b} not in H_edges: return (False, (a, b))  // non-edge excludes H
    return (True, none)                               // H complete => contained
